-- ClassLess: open the class quests that gate a tome to every class.
--
-- GENERATED by scratchpad/rank_sources.py alongside tomes.data -- regenerate
-- them together, or a tome sits behind a quest nobody can pick up.
--
-- Stripping AllowableClasses is not enough on its own: a class quest is also
-- gated by a CLASS condition on its questgiver's gossip menu.
-- =====================================================================

UPDATE `quest_template_addon` SET `AllowableClasses` = 0 WHERE `ID` IN (
    1712, 1713, 1740, 1791, 1792, 1796, 1799, 1947, 1948, 1949, 1950, 1951,
    1952, 1953, 1954, 1955, 1956, 1957, 1958, 2019, 2358, 3095, 3096, 3097,
