  AND `ConditionTypeOrReference` = 15 AND `SourceGroup` IN (
    1403, 1522, 2381, 2383, 2384, 3642, 3921, 3924, 3925, 4010, 4023, 4104,
    4466, 4467, 4471, 4473, 4482, 4484, 4485, 4502, 4503, 4508, 4511, 4512,
